ALTER TABLE public.monthly_bills ADD COLUMN legacy_import boolean NOT NULL DEFAULT false;
CREATE OR REPLACE FUNCTION public.validate_monthly_bill() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE paid numeric; BEGIN IF TG_OP='DELETE' THEN IF EXISTS(SELECT 1 FROM public.payment_allocations WHERE bill_id=OLD.id) OR OLD.opening_paid>0 THEN RAISE EXCEPTION 'Paid bills cannot be deleted'; END IF; RETURN OLD; END IF; PERFORM 1 FROM public.customers WHERE id=NEW.customer_id FOR UPDATE; IF TG_OP='INSERT' AND NEW.opening_paid<>0 AND auth.uid() IS NOT NULL THEN RAISE EXCEPTION 'Record a collection instead'; END IF; IF TG_OP='UPDATE' THEN IF auth.uid() IS NOT NULL AND (NEW.customer_id<>OLD.customer_id OR NEW.billing_month<>OLD.billing_month OR NEW.opening_paid<>OLD.opening_paid OR NEW.legacy_import<>OLD.legacy_import) THEN RAISE EXCEPTION 'Bill identity and historical credit cannot change'; END IF; SELECT coalesce(sum(a.amount),0)+OLD.opening_paid INTO paid FROM public.payment_allocations a JOIN public.payments p ON p.id=a.payment_id WHERE a.bill_id=OLD.id AND p.voided_at IS NULL; IF NEW.amount<paid THEN RAISE EXCEPTION 'Amount cannot be below payments'; END IF; END IF; RETURN NEW; END $$;
UPDATE public.monthly_bills b SET legacy_import=true,billing_month=CASE WHEN c.due_amount=0 THEN date_trunc('month',c.due_date-interval '1 month')::date ELSE b.billing_month END,due_date=CASE WHEN c.due_amount=0 THEN (c.due_date-interval '1 month')::date ELSE b.due_date END FROM public.customers c WHERE c.id=b.customer_id;
CREATE FUNCTION public.zone_contains(poly jsonb,latitude double precision,longitude double precision) RETURNS boolean LANGUAGE plpgsql IMMUTABLE SET search_path=public AS $$ DECLARE i integer; j integer; xi float8; yi float8; xj float8; yj float8; inside boolean:=false; BEGIN IF jsonb_typeof(poly)<>'array' OR jsonb_array_length(poly)<3 THEN RETURN false; END IF; j:=jsonb_array_length(poly)-1; FOR i IN 0..jsonb_array_length(poly)-1 LOOP yi:=(poly->i->>0)::float8; xi:=(poly->i->>1)::float8; yj:=(poly->j->>0)::float8; xj:=(poly->j->>1)::float8; IF abs((longitude-xi)*(yj-yi)-(latitude-yi)*(xj-xi))<1e-10 AND longitude BETWEEN least(xi,xj) AND greatest(xi,xj) AND latitude BETWEEN least(yi,yj) AND greatest(yi,yj) THEN RETURN true; END IF; IF (yi>latitude)<>(yj>latitude) THEN IF longitude<(xj-xi)*(latitude-yi)/(yj-yi)+xi THEN inside:=NOT inside; END IF; END IF; j:=i; END LOOP; RETURN inside; END $$;
CREATE FUNCTION public.assign_customer_zone() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE ids uuid[]; BEGIN IF TG_OP='UPDATE' AND NEW.lat=OLD.lat AND NEW.lng=OLD.lng AND NEW.zone_id IS NOT DISTINCT FROM OLD.zone_id THEN RETURN NEW; END IF; SELECT array_agg(id) INTO ids FROM public.zones WHERE public.zone_contains(polygon,NEW.lat,NEW.lng); IF cardinality(ids)=1 THEN NEW.zone_id:=ids[1]; ELSIF NEW.zone_id IS NOT NULL AND NOT coalesce(NEW.zone_id=ANY(ids),false) THEN RAISE EXCEPTION 'Selected zone does not contain customer coordinates'; ELSIF cardinality(ids)>1 AND NEW.zone_id IS NULL THEN RAISE EXCEPTION 'Coordinates overlap multiple zones; select a containing zone'; END IF; RETURN NEW; END $$;
CREATE TRIGGER assign_customer_zone BEFORE INSERT OR UPDATE ON public.customers FOR EACH ROW EXECUTE FUNCTION public.assign_customer_zone();
CREATE FUNCTION public.validate_zone_polygon() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE p jsonb; BEGIN IF jsonb_typeof(NEW.polygon)<>'array' OR jsonb_array_length(NEW.polygon)<3 OR jsonb_array_length(NEW.polygon)>2000 THEN RAISE EXCEPTION 'Polygon requires 3 to 2000 vertices'; END IF; FOR p IN SELECT * FROM jsonb_array_elements(NEW.polygon) LOOP IF jsonb_typeof(p)<>'array' OR jsonb_array_length(p)<>2 OR (p->>0)::float8 NOT BETWEEN -90 AND 90 OR (p->>1)::float8 NOT BETWEEN -180 AND 180 THEN RAISE EXCEPTION 'Invalid polygon coordinates'; END IF; END LOOP; RETURN NEW; END $$;
CREATE TRIGGER validate_zone_polygon BEFORE INSERT OR UPDATE ON public.zones FOR EACH ROW EXECUTE FUNCTION public.validate_zone_polygon();
CREATE FUNCTION public.reconcile_zone_customers() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c record; ids uuid[]; target uuid; BEGIN FOR c IN SELECT * FROM public.customers LOOP SELECT array_agg(id) INTO ids FROM public.zones WHERE public.zone_contains(polygon,c.lat,c.lng); target:=CASE WHEN cardinality(ids)=1 THEN ids[1] WHEN c.zone_id=ANY(ids) THEN c.zone_id ELSE NULL END; IF cardinality(ids)>1 AND target IS NULL THEN CONTINUE; END IF; IF target IS DISTINCT FROM c.zone_id THEN UPDATE public.customers SET zone_id=target WHERE id=c.id; END IF; END LOOP; RETURN NEW; END $$;
CREATE TRIGGER reconcile_zone_customers AFTER INSERT OR UPDATE OF polygon ON public.zones FOR EACH ROW EXECUTE FUNCTION public.reconcile_zone_customers();
CREATE FUNCTION public.list_staff_accounts() RETURNS TABLE(user_id uuid,email text,role public.app_role,collector_id uuid) LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_admin() THEN RAISE EXCEPTION 'Admin required'; END IF; RETURN QUERY SELECT u.id,u.email::text,r.role,r.collector_id FROM auth.users u LEFT JOIN public.user_roles r ON r.user_id=u.id ORDER BY u.created_at; END $$;
REVOKE ALL ON FUNCTION public.list_staff_accounts() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.list_staff_accounts() TO authenticated;
CREATE FUNCTION public.set_staff_role(p_user uuid,p_role public.app_role,p_collector uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_admin() THEN RAISE EXCEPTION 'Admin required'; END IF; IF p_user=auth.uid() AND p_role<>'admin' THEN RAISE EXCEPTION 'Cannot remove your own admin access'; END IF; IF p_role='collector' AND p_collector IS NULL THEN RAISE EXCEPTION 'Assign a collector'; END IF; INSERT INTO public.user_roles(user_id,role,collector_id) VALUES(p_user,p_role,CASE WHEN p_role='admin' THEN NULL ELSE p_collector END) ON CONFLICT(user_id) DO UPDATE SET role=excluded.role,collector_id=excluded.collector_id; END $$;
REVOKE ALL ON FUNCTION public.set_staff_role(uuid,public.app_role,uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.set_staff_role(uuid,public.app_role,uuid) TO authenticated;
REVOKE INSERT,UPDATE,DELETE ON public.user_roles FROM authenticated;
INSERT INTO public.monthly_bills(customer_id,billing_month,amount,due_date) SELECT c.id,m::date,c.monthly_bill,(m+(c.billing_day-1)*interval '1 day')::date FROM public.customers c CROSS JOIN LATERAL generate_series(c.billing_start_month,date_trunc('month',timezone('Asia/Dhaka',now())),interval '1 month')m WHERE c.recurring_enabled AND c.monthly_bill>0 ON CONFLICT DO NOTHING;